<script setup lang="ts">import {reactive,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {ElMessage} from 'element-plus';import {authApi} from '../api';import {useAuthStore,ApiError} from '@leadnews/shared';const form=reactive({phone:'',password:''}),busy=ref(false),router=useRouter(),route=useRoute(),auth=useAuthStore();async function submit(){busy.value=true;try{const r=await authApi.login(form.phone,form.password);auth.login(r.token,{...(r.user||{})},'APP_USER');ElMessage.success('登录成功');router.replace(String(route.query.redirect||'/'))}catch(e){ElMessage.error(e instanceof ApiError?e.message:'登录失败')}finally{busy.value=false}}</script>
<template><main class="login-wrap"><section class="login-card"><div class="eyebrow">LEADNEWS</div><h1>欢迎回来</h1><p class="meta">登录后可点赞并管理搜索历史</p><el-form class="stack" style="margin-top:24px" @submit.prevent="submit"><el-input v-model="form.phone" maxlength="11" placeholder="手机号"/><el-input v-model="form.password" type="password" show-password placeholder="密码"/><el-button type="primary" native-type="submit" :loading="busy">登录</el-button></el-form></section></main></template>
